      "碎盾者": "Shieldbreaker",
      "大量前排战士；前排死亡时强化友军。": "Many front-row warriors; allies grow stronger when a front-row unit dies.",
      "暗影猎手": "Shadow Hunter",
      "幽林之眼": "Eye of the Dark Wood",
      "后排远程与狙击单位可以越过前排。": "Back-row ranged and sniper units can strike over the front row.",
      "翠影女王": "Emerald Shadow Queen",
      "王庭的盗贼女王": "Thief Queen of the Royal Court",
      "统御整个哥布林王庭的盗贼女王，每个行动回合都会呼来两名普通哥布林。": "The thief queen who rules the entire goblin court; every action turn she calls in two ordinary goblins.",
      "无尽绿潮": "Endless Green Tide",
      "每个敌方行动回合，在空位免费召唤2个普通哥布林。": "Each enemy action turn, summon 2 ordinary goblins in empty slots for free.",
      "丰穗战母·布蕾娅": "Harvest War Mother Breya",
      "金麦农场的熊族统领": "Bear Chieftain of Golden Wheat Farm",
      "守护熊族新家园的战母。每回合召唤丰穗近卫，每3回合强化场上全部熊族。": "The war mother guarding the bears' new home. Summons a Harvest Guard every turn, and every 3 turns empowers all bears on the board.",
      "护田战令": "Field Guard Decree",
      "每个敌方行动回合召唤1个5攻/7血的丰穗近卫。": "Each enemy action turn, summon a 5/7 Harvest Guard.",
      "丰收之怒": "Wrath of Harvest",
      "每3个敌方行动回合，使场上所有熊族随从获得+1/+2。": "Every 3 enemy action turns, give all bear minions on the board +1/+2.",
      "碧露大贤者·涅芙莉": "Great Sage Nephrie of the Azure Dew",
      "梦幻森林的史莱姆引路者": "Slime Guide of the Dream Forest",
      "拒绝离开故土的大贤者。每个行动回合恢复首领和全部史莱姆生命，每3回合分裂出两名碧露近卫。": "A great sage who refuses to leave her homeland. Each action turn she heals herself and all slimes, and every 3 turns splits off two Azure Dew Guards.",
      "不灭胶质": "Undying Gel",
      "每个敌方行动回合，为首领恢复10点生命，并为所有史莱姆随从恢复5点生命。": "Each enemy action turn, restore 10 Health to the boss and 5 Health to all slime minions.",
      "碧露分裂": "Azure Dew Division",
      "每3个敌方行动回合，免费召唤2个4攻/12血碧露近卫。": "Every 3 enemy action turns, summon 2 4/12 Azure Dew Guards for free.",
      "森林狼王": "Forest Wolf King",
      "裂月之牙": "Fang of the Riven Moon",
      "每3回合召唤幼狼；每4回合发动狼王咆哮。": "Summons a Wolf Cub every 3 turns; unleashes the Wolf King's Howl every 4 turns.",
      "狼王号令": "Wolf King's Command",
      "每3个敌方回合，在空位免费召唤1只幼狼。": "Every 3 enemy turns, summon 1 Wolf Cub in an empty slot for free.",
      "裂月咆哮": "Riven Moon Howl",
      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "Every 4 enemy turns, all wolf minions permanently gain +1 Attack.",
      "银灰狼女猎手": "Silver-Grey Wolf Huntress",
      "千枝城的灰牙首领": "Greyfang Leader of Thousand Branch City",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "The wolf chieftain who evaded the Emerald City's pursuers and seized the ruins of Thousand Branch City. Every turn she calls a swift grey wolf into battle.",
      "灰狼增援": "Grey Wolf Reinforcements",
      "每个敌方行动回合，召唤1只4攻/1血、可立即攻击随从的突击灰狼。": "Each enemy action turn, summon a 4/1 Assault Grey Wolf that can attack minions immediately.",
      "千枝城魔族军官团": "Thousand Branch Demon Officer Corps",
      "拒绝退避的重建者": "Rebuilders Who Refuse to Retreat",
      "第五关剧情结束后驻扎于千枝城的魔族据点。随从均为20攻/200血，属于长期挑战内容。": "The demon stronghold stationed in Thousand Branch City after Chapter 5's story. All minions are 20/200 — long-term challenge content.",
      "千枝城驻军": "Thousand Branch Garrison",
      "使用20攻/200血的魅魔、龙族与开智战兽压制战场。": "Overwhelms the battlefield with 20/200 succubi, dragonkin and awakened war beasts.",
