      "麦田稻草魔像": "Wheatfield Straw Golem",
      "留守的农民夫妇": "The Farming Couple Who Stayed",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "Easy now, young one. Those bears haven't killed anyone here. When they came to the farm, they only drove the villagers off toward the royal capital.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "We stayed because we never sensed any hostility from them. At first they didn't even know how to hold a plow—they just churned the fields into a mess by brute force.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "Later we taught the bear men to repair the canals and sow wheat, and taught the bear women to tend the hives and bring in the harvest. They learn slowly, but they never waste food.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "They save the warmest spot in the barn for their cubs, and they bring the first sack of new wheat to our door. At least in our eyes, they're not as vile as the rumors say.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "If you must go on, see it with your own eyes before you judge. What happened here may not be a simple case of monsters seizing a village.",
      "露珠幼母": "Dewdrop Brood Mother",
