      "神秘泉水": "Mysterious Spring",
      "银色泉水从刻有月纹的岩石间涌出。": "Silver spring water wells up between moon-carved rocks.",
      "喝下泉水": "Drink from the spring",
      "恢复10点生命": "Restore 10 Health",
      "装满水壶": "Fill your waterskin",
      "收藏中获得1张治疗药剂": "Add 1 Healing Potion to your collection",
      "废弃营地": "Abandoned Camp",
      "余烬尚温，帐篷里似乎遗留着补给。": "The embers are still warm; supplies seem to have been left in the tents.",
      "仔细搜索": "Search carefully",
      "50%获得30金币，否则受到5点伤害": "50%: gain 30 gold; otherwise take 5 damage",
      "立刻离开": "Leave at once",
