      "让荣誉由守住阵线的人证明": "Let honor be proven by those who hold the line",
      "铁炉擂台": "Ironforge Ring",
      "你的盾看上去像报名处送的纪念品": "Your shield looks like a souvenir from the registration desk",
      "苍叶精灵": "Greenleaf Elves",
      "道路测绘、林地公约与公开军校": "Road surveys, woodland accords and open military academies",
      "赤焰学院": "Crimson Flame Academy",
      "把火焰从破坏变成可计算的战术": "Turning fire from destruction into calculable tactics",
      "裂牙兽人": "Riftfang Orcs",
      "统一军粮、公开军籍与按功授衔": "Unified rations, public military records and rank by merit",
      "雷铜矮人": "Thundercopper Dwarves",
      "标准化工坊、跨城铁路与工匠保险": "Standardized workshops, intercity railways and artisan insurance",
      "寒骨亡者": "Frostbone Undead",
      "让亡者也能申诉和立契的王国法庭": "A royal court where even the dead may petition and sign contracts",
      "月林精灵": "Moonwood Elves",
      "公共林地、识字学校与巡林员制度": "Public woodlands, literacy schools and the ranger system",
      "王都暗巷": "Capital Back Alleys",
      "你每犹豫一秒，我就多想好一种让你退场的姿势": "Every second you hesitate, I think of one more way to knock you out",
      "北境霜冠卫": "Northern Frostcrown Guard",
      "让王冠的重量落在承担责任的人肩上": "Let the weight of the crown rest on the shoulders of those who bear responsibility",
      "荒原牛头人": "Wasteland Taurens",
      "灌溉渠、公共粮仓与灾年赈济": "Irrigation canals, public granaries and famine relief",
      "圣辉教会": "Church of Holy Radiance",
      "让力量先学会克制，再谈胜利": "Let power first learn restraint, then speak of victory",
      "王立药剂院": "Royal Alchemy Institute",
      "用剂量、记录与复验取代碰运气": "Replacing luck with dosage, records and re-testing",
      "赤鳞蜥人": "Redscale Lizardfolk",
      "下水道、防疫隔离与跨种族医馆": "Sewers, quarantine and cross-species clinics",
      "沙海边军": "Sandsea Border Army",
      "让每一支箭都对得起身后的商旅": "Let every arrow be worthy of the caravans behind it",
      "黑潮舰队": "Black Tide Fleet",
      "我打沉过的船比你打赢过的比赛还多": "I've sunk more ships than you've won matches",
      "魔裔猎手": "Demonblood Hunters",
      "允许魔裔凭考核加入边境军团的军籍改革": "Military reform letting demon-blooded folk join the border legion by examination",
      "鸦木学派": "Ravenwood School",
      "把诅咒拆成能够理解和反制的符文结构": "Breaking curses down into rune structures that can be understood and countered",
      "银冠王室": "House of the Silver Crown",
      "你能和我同场，是本届王冠杯最大的平民福利": "Sharing the field with me is the greatest commoner perk of this year's Crown Cup",
      "北地蛮族": "Northland Barbarians",
      "我会把你的战术连同桌子一起劈开": "I'll cleave your tactics in half along with the table",
      "星界学院": "Astral Academy",
      "用观测和演算让星象不再只是预言": "Using observation and calculation so the stars are no longer mere prophecy",
      "战矛军团": "Warspear Legion",
      "等你看清我的矛尖，裁判已经在数秒了": "By the time you see my spear tip, the referee is already counting",
      "开智熊族": "Awakened Bearfolk",
      "蜂房、农具、冬粮制度与农学课堂": "Beehives, farm tools, winter grain reserves and agronomy classes",
      "红狐族": "Red Foxfolk",
      "公开商会、契约法与不问出身的城市户籍": "Open guilds, contract law and city residency regardless of origin",
      "天穹寺": "Skyvault Temple",
      "在出拳前先学会为何收拳": "Before throwing a punch, learn why to hold it back",
      "王都防疫署": "Capital Epidemic Bureau",
      "用统计、隔离和清洁水源战胜瘟疫": "Defeating plague with statistics, quarantine and clean water",
      "雄狮族": "Lionfolk",
      "按能力授衔、伤兵抚恤与军属安置": "Rank by ability, pensions for the wounded and support for soldiers' families",
      "红莲法塔": "Red Lotus Spire",
      "你的牌组很适合生火，可惜这里已经够热了": "Your deck is great kindling—too bad it's already hot enough in here",
      "磐石石裔": "Bedrock Stoneborn",
      "桥梁工法、公共工程与有期限的劳务契约": "Bridge engineering, public works and fixed-term labor contracts",
      "月夜血族": "Moonlit Vampires",
      "夜间工坊、公民登记与对异族有效的同一部法律": "Night workshops, citizen registration and one law that applies to every race",
      "钢鬃野猪人": "Steelmane Boarfolk",
      "军团食堂、伤残抚恤与面向所有人的征兵考核": "Legion mess halls, disability pensions and recruitment exams open to all",
      "高等精灵": "High Elves",
      "王立学院不问血统的招生与公开考试": "Royal Academy admissions regardless of bloodline, with open examinations",
      "沼泽蛙人": "Marsh Frogfolk",
      "排水工程、药材贸易与湿地保护法": "Drainage works, herb trade and wetland protection laws",
      "苍鹰翼人": "Azure Hawk Winged Folk",
      "驿站航空塔、开放军籍与统一空域规则": "Relay air towers, open enlistment and unified airspace rules",
      "暗影教团": "Shadow Order",
      "你带来了二十四张牌，我只需要一张墓志铭": "You brought twenty-four cards; I only need one epitaph",
      "黄铜构装体": "Brass Constructs",
      "承认拥有意志的构装体也能成为公民": "Recognizing that constructs with a will can be citizens too",
      "太阳神殿": "Temple of the Sun",
      "让胜者有照亮败者道路的气度": "Let the victor have the grace to light the loser's path",
      "风暴高塔": "Storm Tower",
      "记录气压与魔力，让雷霆服从推演": "Recording pressure and magic so thunder obeys calculation",
      "工会契约、城市桥梁与巨型工种的安全规范": "Union contracts, city bridges and safety codes for giant-sized trades",
