      "暮色契约会": "Twilight Covenant",
      "你的每个选择都在我的契约里标好了价钱": "Every choice you make already has a price marked in my contract",
      "铜须矮人": "Copperbeard Dwarves",
      "同工同酬的工匠行会与公开技术标准": "Artisan guilds with equal pay and open technical standards",
      "枭羽人": "Owlfolk",
      "夜校、公共图书馆与向异族开放的考试": "Night schools, public libraries and examinations open to other races",
      "公路网、驿站通行权与牧道协定": "Road networks, relay-station passage rights and herding-route accords",
      "赤潮海盗团": "Red Tide Pirates",
      "别数法力了，数数自己还剩几颗牙吧": "Stop counting mana—count how many teeth you have left",
      "碧鳞娜迦": "Jadescale Naga",
      "净水渠、跨种族医馆与河道共同管理": "Clean water canals, cross-species clinics and shared river management",
      "沙幕王庭": "Sandveil Court",
      "让王族先承担风险，再接受欢呼": "Let royals bear the risk first, then accept the cheers",
      "白狼族": "White Wolf Clan",
      "合法军籍、家属安置与面向兽族的城市教育": "Legal enlistment, family resettlement and city education for beastfolk",
      "不灭凰族": "Undying Phoenixes",
      "火灾救援、灾后重建与对重生者的身份登记": "Fire rescue, disaster reconstruction and identity registration for the reborn",
      "黑锋骑士团": "Blackedge Order",
      "让锋刃只指向准备好应战的人": "Let the blade point only at those ready to fight",
      "蒲公英花灵": "Dandelion Fae",
      "市集、印刷术与允许异族登台的演出许可": "Markets, printing and performance licenses that let other races take the stage",
      "血斧角斗场": "Bloodaxe Arena",
      "裁判最好离远点，我的胜利通常会溅到前三排": "The referee should stand back—my victories usually splash the first three rows",
      "晶辉学院": "Crystal Radiance Academy",
      "用晶体测量魔力，让法术可以被复现": "Measuring magic with crystals so spells can be reproduced",
      "鹿角兽人": "Antlered Beastfolk",
      "护林法、共享牧道与边地自治议会": "Forest protection laws, shared herding routes and frontier self-rule councils",
      "机巧侏儒": "Clockwork Gnomes",
      "专利制度、公开船坞与事故追责": "Patent systems, open shipyards and accountability for accidents",
      "虚空观测站": "Void Observatory",
      "用长期观测区分天启、幻觉和噪声": "Long-term observation to tell revelation from illusion and noise",
      "黄金狮鹫族": "Golden Griffins",
      "空骑军籍、兽族居住权与救援航线": "Sky-rider enlistment, beastfolk residency and rescue flight routes",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "I didn't join the kingdom to become human, but because here I can stay myself and move forward on my own merit.",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "Bloodline only decides where we're born; institutions and choices decide whether we can stand side by side here.",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "Today I don't represent submission, but a kingdom where other races can compete openly and win applause fair and square.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "Beautiful. Pushing me this far proves the capital truly welcomes an opponent worthy of respect.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "I won't prove those prejudices right that other races belong hidden in the wilds. Come—final round!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "You win. May this arena keep proving it: humans and other races can compete without hating one another.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "Play faster. The audience didn't buy tickets to watch you ponder life.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "You call that a battle line? My laundry line is harder to break through.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "Relax, I'll leave you some dignity—I'll at least wait for the referee's call before I laugh.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "Stop looking at the scoreboard. It won't switch sides just because you stare at it long enough.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "That last move was decent. But to shut me up, you still have one last stretch to go.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "Don't wave to the crowd yet! I'm just saving my comeback for when it's loudest.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "You win today. Next time I'll beat you first, then file a complaint about this floor that obviously favors you.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "Don't mind me, I'm recording your play habits. The truly dangerous data often comes from confident people.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "Every trade narrows down the answer. A few more rounds and you'll have only one choice left.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "The arena is more honest than the lab: wrong theories lose Health on the spot.",
      "放心，若你击败我，我会如实把结论写进报告。": "Rest assured, if you beat me, I'll write the conclusion into my report faithfully.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "The data deviates from the prediction. Good—research without surprises is the most boring kind.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "The sample is now verifying the researcher... I admit this result is very convincing.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "Conclusion confirmed: your in-the-moment judgment beats my model. The next draft of my paper will say so.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "There are no true enemies in the arena, only people willing to show their skills in the sunlight.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "Don't abandon the line to save your life. Honor comes from taking risks, not avoiding them.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "The audience remembers the result; a warrior should remember the choices made under pressure.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "Don't hold back. The best way to respect an opponent is to bring the strength that truly wants to win.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "A fine frontal breakthrough. Pain passes; losing your judgment is the real defeat.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "Just one last point of Health—perfect for testing the last shred of will.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "The match is decided. I've memorized your tactics, and I'll save my applause for those who deserve it.",
      "并": "and",
      "，它们可以立即攻击": ", and they can attack immediately",
      "和": "and",
