      "生命": "Health",
      "战场上没有狼类随从，技能未强化任何单位。": "There are no wolf minions on the battlefield; the skill empowered no units.",
      "🐺 狼王咆哮发动！": "🐺 Wolf King's Howl unleashed!",
      "接管战场，准备主动反击": "Take over the battlefield and prepare to strike back",
      "封锁全部前排": "Seal off the entire front row",
      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "The four succubus officers refuse to withdraw and counterattack at once with 20 Attack; the squad will be driven back, but Chapter 5 still counts as cleared.",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "The four succubus officers do not attack; they only maintain the barrier, buying two turns for their comrade's escape.",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "Thousand Branch counterattack begins: the four succubus officers strike at the squad one by one with 20 Attack.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "The four officers' assault breaks the line, and the demon alliance's vanguard crosses the rift to seize the ruins; the squad is forced out of Thousand Branch City.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "The four succubus officers routed the squad, but the Silver-Grey Wolf Huntress has already been defeated: Chapter 5's story is complete, and all loot and clear rewards are granted as usual.",
      "你的英雄倒下了。冒险结束。": "Your hero has fallen. The adventure is over.",
