      "追寻银灰狼女猎手": "Track the Silver-Grey Wolf Huntress",
      "追寻碧露大贤者": "Seek the Great Sage of the Azure Dew",
      "踏入金麦农场": "Enter Golden Wheat Farm",
      "会见丰穗战母": "Meet the Harvest War Mother",
      "进军王庭": "March on the Court",
      "挑战翠影女王": "Challenge the Emerald Shadow Queen",
      "击穿战线": "Break the Battle Line",
      "直面狼王": "Face the Wolf King",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "Chapter 5 lies in the ancient ruins south of the Emerald City. Grey wolves and other beasts expand their territory with speed and ambushes; at the end you face the Silver-Grey Wolf Huntress.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "Chapter 4 has twenty slime boss nodes. They have thick Health, low Attack and keep regenerating; follow the glowing stream deep into the forest to face Great Sage Nephrie of the Azure Dew.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "Chapter 3 has twenty bear boss nodes and a farmhouse. Follow the farm trails to investigate the occupied village, and finally face Harvest War Mother Breya.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "Chapter 2 has twenty boss nodes. Push along the goblin army's defenses and finally face the Emerald Shadow Queen with 200 Health.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "Deploy your army across four battle lanes with front and back rows, tear open a gap and cross thirteen Misty Forest nodes. Every victory becomes strength for the next expedition.",
      "重新开始本关": "Restart This Chapter",
      "当前没有伤员": "No injured units",
      "单机卡牌闯关冒险": "A single-player card adventure",
      "关卡选择": "Chapter Select",
