      "设置": "Settings",
      "队伍营地": "Team Camp",
      "每项卡牌训练或救治服务均需30金币。阵亡的真实随从会进入伤员名单，救治后才能重新出战。": "Each card training or healing service costs 30 gold. Real minions that die go onto the injured list and must be healed before they can fight again.",
      "⚔️ 随从训练 · 30金币": "⚔️ Minion Training · 30 gold",
      "选择任意一张未满级随从牌，增加2点经验": "Choose any minion card below max level to gain 2 XP",
      "✨ 法术训练 · 30金币": "✨ Spell Training · 30 gold",
      "选择任意一张未满级法术牌，增加2点经验": "Choose any spell card below max level to gain 2 XP",
      "🗡️ 武器训练 · 30金币": "🗡️ Weapon Training · 30 gold",
      "选择任意一张未满级武器牌，增加2点经验": "Choose any weapon card below max level to gain 2 XP",
