      "永久成长": "Permanent Growth",
      "战斗经验、法力和技能成长会跨冒险保存。": "Battle XP, mana and skill growth carry over between adventures.",
      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "Once Captain of the Royal Guard in the capital. As beasts awakened one after another, he decided that guarding a single capital was not nearly enough, so he left it, gathered his own squad, and set out to quell unrest across the land.",
      "生命上限": "Max Health",
      "统领试炼": "Commander Trials",
      "英雄经验": "Hero XP",
      "牌组上限": "Deck Limit",
