      "冒险通关": "Adventures Cleared",
      "技能最高3级。每赢得一场竞技场比赛，当前装备技能获得2点经验；夺冠还会获得决赛对手的英雄技能。": "Skills go up to level 3. Each arena match won gives your equipped skill 2 XP; winning the tournament also grants the finalist's hero skill.",
      "竞技场传承": "Arena Legacy",
