      "开始试炼": "Start Trial",
      "第七关“女王的低语”已经可以进入": "Trial 7, \"The Queen's Whisper\", is now open",
      "击败第一关第一个Boss，取得女王血河水后，才能进入最终试炼。": "Defeat the first boss of Chapter 1 and obtain the Queen's blood river water to enter the final trial.",
      "海港城市 · 老兵训练场": "Harbor City · Veterans' Training Grounds",
      "归乡之战幸存者的七堂课": "Seven Lessons from Survivors of the War of Homecoming",
      "每关首次通关永久增加1点最大法力；没有碎片，也没有总上限。重复挑战不会重复获得法力。": "The first clear of each trial permanently adds 1 Max Mana; no shards and no overall cap. Repeat clears don't grant mana again.",
      "返回世界地图": "Return to World Map",
      "这项试炼尚未解锁。": "This trial isn't unlocked yet.",
      "你再次完成了这项试炼；首次通关奖励已经领取。": "You completed this trial again; the first-clear reward has already been claimed.",
      "统领试炼完成": "Commander Trial Complete",
      "返回训练场": "Return to Training Grounds",
      "试炼暂未通过": "Trial Not Yet Passed",
      "试炼不会消耗远征生命或地图进度。调整战术后可以立即重试。": "Trials don't consume expedition Health or map progress. Adjust your tactics and retry right away.",
      "请先击败森林狼王解锁第二关。": "Defeat the Forest Wolf King first to unlock Chapter 2.",
