      "已加入英雄技能收藏，可在英雄档案装备。": "Added to your hero skill collection; equip it in the Hero Profile.",
      "，你成为本届王冠杯冠军！": ", you are this year's Crown Cup Champion!",
      "。下一名对手已经就位。": ". Your next opponent is ready.",
      "竞技场胜利": "Arena Victory",
