      "本届赛事已经结束，已获得的晋级奖金全部保留。": "This tournament is over; all advancement prizes you earned are kept.",
      "查看赛果": "View Results",
      "魔族重建据点": "Demon Rebuilt Stronghold",
      "· 尚未挑战": "· not yet challenged",
      "与留守的农民夫妇交谈": "Talk to the farming couple who stayed",
      "先抵达相邻农田节点": "Reach the adjacent farmland node first",
      "农民夫妇": "Farming Couple",
      "千枝城废墟二十野兽首领路线图": "Route map of twenty beast bosses in the Thousand Branch Ruins",
      "梦幻森林二十史莱姆首领路线图": "Route map of twenty slime bosses in the Dream Forest",
      "金麦农场二十首领路线图": "Route map of twenty bosses at Golden Wheat Farm",
      "哥布林王庭二十节点路线图": "Route map of twenty nodes in the Goblin Court",
      "迷雾森林十三节点路线图": "Route map of thirteen nodes in the Misty Forest",
      "千枝城古城废墟": "Thousand Branch Ruins",
      "梦幻森林": "Dream Forest",
      "金麦农场": "Golden Wheat Farm",
      "哥布林王庭": "Goblin Court",
      "迷雾森林远征": "Misty Forest Expedition",
      "灰狼和其他野兽速度极快，许多单位登场即可攻击。击败全部节点后，魔族联军会在废墟建立据点，之后可以反复挑战强大的军官与魔族军队。": "Grey wolves and other beasts are extremely fast, and many units can attack as soon as they enter. After you defeat every node, the demon alliance builds a stronghold in the ruins, where you can repeatedly challenge powerful officers and demon troops.",
      "沿发光溪流与林间小径推进。每个史莱姆首领都会治疗自身与随从；击败节点后开启所有相邻路线，首胜卡牌会在战后揭晓。": "Advance along the glowing stream and forest paths. Every slime boss heals herself and her minions; defeating a node opens all adjacent routes, and first-win cards are revealed after battle.",
      "沿金色路线推进。击败节点后会开启所有相邻路线；抵达农舍旁的节点后，可与留守的农民夫妇交谈。每个首领的首胜奖励会在战后揭晓。": "Advance along the golden route. Defeating a node opens all adjacent routes; once you reach the node beside the farmhouse, you can talk to the farming couple who stayed. Each boss's first-win reward is revealed after battle.",
      "击败任一节点即可开启相邻路线；翠影女王会在抵达右上方终点后开放。大部分节点由哥布林军团驻守。": "Defeating any node opens the adjacent routes; the Emerald Shadow Queen becomes available once you reach the final node in the upper right. Most nodes are held by the goblin army.",
      "金边节点由更强的敌人驻守；首次击败会获得未知战利品。击败节点后仍可回到岔路挑战相邻路线。": "Gold-rimmed nodes are held by stronger enemies; the first defeat grants unknown loot. After defeating a node you can still return to the fork to challenge adjacent routes.",
      "击败一个节点后，所有相邻的未完成节点都会解锁。战败不会清空本关进度，切换关卡也会分别保存。": "After you defeat a node, all adjacent unfinished nodes unlock. Losing a battle doesn't wipe this chapter's progress, and each chapter is saved separately when you switch.",
      "⭐ 本轮": "⭐ This run",
      "⚔️ 已完成": "⚔️ Completed",
      "🛡️ 失败": "🛡️ Failed",
      "退出当前关卡": "Leave Chapter",
      "先抵达农舍旁的农田节点。": "Reach the farmland node beside the farmhouse first.",
      "金麦农场 · 留守者的证言": "Golden Wheat Farm · Testimony of Those Who Stayed",
      "他们并不要求你放下武器，只希望你在见到丰穗战母之前，先知道这些熊族并未伤害原来的村民。": "They don't ask you to lay down your weapons—only that before you meet the Harvest War Mother, you know these bears never harmed the original villagers.",
      "我会亲眼判断": "I'll judge with my own eyes",
      "请先完成第五关结局，解锁千枝城魔族重建据点。": "Complete Chapter 5's ending first to unlock the demon stronghold in Thousand Branch City.",
      "极限挑战": "Ultimate Challenge",
      "千枝城驻军暂时退却": "Thousand Branch Garrison Pulls Back",
      "你击退了不可一世的魔族驻军，获得500金币。她们仍会继续重建千枝城，之后仍可再次挑战。": "You repelled the arrogant demon garrison and earned 500 gold. They will keep rebuilding Thousand Branch City, and you can challenge them again later.",
      "返回废墟地图": "Return to Ruins Map",
      "魔族军官守住了据点": "The Demon Officers Held the Stronghold",
      "20攻/200血的驻军压倒了小队。这场失败不会重置第五关进度，也不会造成额外惩罚。": "The 20/200 garrison overwhelmed the squad. This defeat won't reset Chapter 5 progress or cause any extra penalty.",
      "每一列的前排会保护其身后的后排。": "Each lane's front row protects the back row behind it.",
      "击败前排后，才能普通攻击该列后排。": "Only after defeating the front row can you normally attack that lane's back row.",
      "前后排全部为空时，该路线被突破。": "When both rows are empty, that lane is breached.",
      "通过突破路线可以直接攻击敌方英雄。": "You can attack the enemy hero directly through a breached lane.",
