      "梦幻森林归于寂静": "The Dream Forest Falls Silent",
      "金麦农场的战事落幕": "The Fighting at Golden Wheat Farm Ends",
      "哥布林王庭陷落": "The Goblin Court Falls",
      "密林重见曙光": "Dawn Returns to the Deep Woods",
      "你击败银灰狼女猎手后，五位魅魔军官没有继续退避。她们救下狼族首领，以20点攻击的力量击溃小队，并决定在千枝城废墟建立魔族据点、重建这座千年前的共居之城。第五关奖励照常结算，英雄等级上限提升至25级；废墟地图上已经开放可反复挑战的魔族驻军。": "After you defeat the Silver-Grey Wolf Huntress, the five succubus officers stop retreating. They rescue the wolf chieftain, crush the squad with 20 Attack, and decide to build a demon stronghold in the Thousand Branch Ruins to rebuild this city where peoples lived together a thousand years ago. Chapter 5 rewards are granted as usual and the hero level cap rises to 25; a demon garrison you can challenge repeatedly is now open on the ruins map.",
      "你击败了碧露大贤者·涅芙莉，迫使史莱姆族群退回森林深处，并将英雄等级上限提升至20级。": "You defeated Great Sage Nephrie of the Azure Dew, forcing the slimes back into the depths of the forest, and raised the hero level cap to 20.",
      "你击败了丰穗战母·布蕾娅，完成第三关并解锁东部梦幻森林与英雄20级上限。": "You defeated Harvest War Mother Breya, completing Chapter 3 and unlocking the Eastern Dream Forest and a hero level cap of 20.",
      "你击败了翠影女王，完成第二关的二十场首领战，并解锁王城南部的金麦农场与英雄15级上限。": "You defeated the Emerald Shadow Queen, completing Chapter 2's twenty boss battles and unlocking Golden Wheat Farm south of the capital and a hero level cap of 15.",
      "你击败了森林狼王，并解锁第二关与英雄10级上限。最大法力只在统领试炼中提升。": "You defeated the Forest Wolf King, unlocking Chapter 2 and a hero level cap of 10. Max mana only increases through the Commander Trials.",
