      "“{0}”": "“{0}”",
      "{0}：“{1}”": "{0}: “{1}”",
      "罗兰·维克": "Roland Vick",
      "前王都护卫队长": "Former Captain of the Royal Guard",
      "莉瑟尔": "Lisel",
      "薇奥菈": "Viola",
      "赛琳娜": "Selina",
      "格罗姆": "Grom",
      "埃尔德": "Eld",
      "奥斯坦": "Ostan",
      "希尔瓦": "Silva",
      "翠羽射手": "Jadefeather Archer",
      "紫晶魔女": "Amethyst Witch",
      "晨曦圣女": "Dawn Saint",
      "裂角蛮王": "Broken-Horn Warlord",
      "银叶游侠": "Silverleaf Ranger",
      "银盾骑士": "Silvershield Knight",
      "森灵德鲁伊": "Grove Druid",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "The youngest marksman of the forest frontier; her arrows slip through layers of branches to find foes hiding behind the lines.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "A witch who left the mage tower to study the Rift alone, skilled at splitting mana into countless missiles that are hard to dodge.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "A saint sent to the front by the Temple of the Sun, who believes every soldier deserves to stand up once more.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "A warlord of the northern tribes who ignites his warriors' fury with his own blood.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "Leader of the Moonwood rangers, who always makes foes spot archers in the shadows where none should be.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "A veteran of the capital's Dawnlight Order; his shield wall has never taken a step back.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "A druid born of the ancient grove's heart; every sapling she plants grows into an ancient tree that guards the forest.",
      "穿林箭": "Piercing Arrow",
      "奥术飞弹": "Arcane Missiles",
      "晨曦复苏": "Dawn Revival",
      "血怒狂击": "Blood Frenzy",
