      "炭烤肉串": "Charred Skewers",
      "撒满辣椒粉的炭烤肉串，哥布林最爱抢着吃。": "Charcoal-grilled skewers covered in chili powder. Goblins fight over them.",
      "金蜜松饼": "Golden Honey Pancakes",
      "淋上整勺蜂蜜的厚松饼，熊族闻到就走不动路。": "Thick pancakes drowned in honey. Bearfolk stop in their tracks at the smell.",
      "月露果冻": "Moondew Jelly",
      "用月潭露水凝成的清凉果冻，史莱姆会把它整个吞进身体里。": "A cool jelly set from Moonpool dew. Slimes swallow it whole.",
      "炙烤带骨肉": "Roast on the Bone",
      "外焦里嫩的大块带骨肉，狼族会一边啃一边摇尾巴。": "A big roast, crisp outside and tender inside. Wolves wag their tails as they gnaw.",
      "猎人炖锅": "Hunter's Stew",
      "炖了一整夜的浓汤，暖胃也暖心。": "A thick stew simmered all night. Warms the belly and the heart.",
      "丰收宴席": "Harvest Feast",
      "一整桌丰盛的宴席，再倔强的俘虏也会动摇。": "A whole table of rich dishes. Even the most stubborn prisoner will waver.",
      "下矿": "Mining",
      "钻进褐石矿坑挖金子，按好感等级带回金币。": "Digs for gold in the Brownstone mines and brings back coins based on bond level.",
      "种田": "Farming",
      "去营地外的麦田耕种，收获的麦子直接磨成面粉，补充队伍粮食。": "Works the wheat fields outside camp. The harvest is milled into flour for the party's rations.",
