      "每场战斗消耗：随从{0} + 犯人{1} = {2}份粮食；每天日常消耗{3}场的量，共{4}份": "Each battle uses: minions {0} + prisoners {1} = {2} rations. Daily upkeep equals {3} battles, {4} rations in total",
      "现实{0}分钟为游戏里的一天；新的一天可以再投喂每名在押首领一次，队伍会吃掉{1}场战斗的粮食。": "{0} real minutes make one in-game day. Each new day you can feed every captive boss once more, and the party eats {1} battles' worth of rations.",
      "第{0}天": "Day {0}",
