      "🌙 夜晚事件": "🌙 Night Event",
      "好的": "OK",
      "第{0}天：粮食不够日常所需（{1}份），库存已经吃光了。快去金杯餐馆买面粉！": "Day {0}: Not enough rations for daily needs ({1}). The stores are empty—buy flour at the Golden Cup Restaurant!",
      "第{0}天开始：队伍吃掉了{1}份日常口粮，在押首领又可以投喂了。": "Day {0} begins: the party ate {1} daily rations, and captive bosses can be fed again.",
      "粮食不足，队伍饿着肚子出战：本场我方随从攻击-1。": "Not enough rations—the party fights hungry: your minions have -1 Attack this battle.",
