      "未解锁 · 第{0}关已结缘 {1}/{2}": "Locked · Chapter {0} bonded {1}/{2}",
      "最终首领卡牌": "Final Boss Cards",
      "牢房还空着。击败冒险中的首领，它们就会被押回这里。": "The cells are empty. Defeat bosses on your adventures and they'll be brought back here.",
      "已关押 {0}/{1} 名觉醒者。各关的最终首领不在此列：森林狼王战死于密林，其余首领都在最后关头被同族救走。": "{0}/{1} Awakened imprisoned. Each chapter's final boss is not among them: the Forest Wolf King fell in the deep woods, and the others were rescued by their kin at the last moment.",
      "第二关起击败的首领，其首杀奖励卡要与牢里的本人结缘（好感度{0}）后才能出战；继续投喂，每{1}点好感升一级（最高{2} Lv{3}），结缘后每高一级：随从+{4}攻击、+{5}生命，法术效果提升{6}级。最终首领的卡牌要等本关全部在押首领结缘才能使用，等级取其中最低的一位。每名首领每天（现实{7}分钟）只能投喂一次，距离新的一天还有{8}。背包里共有 {9} 份食物。": "From Chapter 2 on, a defeated boss's first-kill reward card can only be used after you bond with that boss in prison (affinity {0}). Keep feeding to gain a level every {1} affinity (up to {2} Lv{3}). Each level above Bonded gives minions +{4} Attack and +{5} Health, and spells +{6} effect levels. A final boss's card unlocks only when every captive boss of that chapter is bonded, and uses the lowest of their levels. Each boss can be fed once per day ({7} real minutes); the next day starts in {8}. You have {9} food items in your backpack.",
      "📖 族群往事": "📖 Tales of the Clans",
      "前往城镇商店": "Go to the Town Shops",
      "返回队伍营地": "Back to Team Camp",
      "后回营": " until return",
      "✅ 今日已干活": "✅ Worked today",
      "{0} 结缘Lv1：{1}；誓约Lv5：{2}": "{0} Bonded Lv1: {1}; Sworn Lv5: {2}",
      "派遣劳动": "Work Detail",
      "结缘后的首领每天可以派出去干一次活，{0}小时（现实{1}分钟）后带着收获回营；干活期间不能投喂。可派 {2} 名 · 在外 {3} 名": "Bonded bosses can be sent to work once per day and return with their haul after {0} hours ({1} real minutes). They can't be fed while away. Available: {2} · Away: {3}",
      "一键派遣（{0}）": "Dispatch All ({0})",
