      "没有可以派遣的首领：需要已结缘、今天还没干过活且在牢里。": "No bosses can be dispatched: they must be bonded, in their cell, and not yet worked today.",
      "派出了{0}名首领去干活，{1}小时后回营。": "Sent {0} bosses to work; back in {1} hours.",
